.container {
  display: flex;               /* activate flexbox */
  flex-direction: row;         /* row | row-reverse | column | column-reverse */
  flex-wrap: wrap;             /* nowrap | wrap | wrap-reverse */

  /* Main axis (row direction by default) */
  justify-content: flex-start; /* flex-start | flex-end | center | space-between | space-around | space-evenly */

  /* Cross axis (column direction by default) */
  align-items: stretch;        /* stretch | flex-start | flex-end | center | baseline */

  /* Space between items */
  gap: 16px;                   /* row-gap and column-gap combined */
  gap: 12px 24px;              /* row-gap column-gap */
}

.item {
  /* flex shorthand: grow shrink basis */
  flex: 1;          /* flex: 1 1 0 — fill available space equally */
  flex: auto;       /* flex: 1 1 auto — grow/shrink from intrinsic size */
  flex: none;       /* flex: 0 0 auto — fixed size, no grow/shrink */
  flex: 0 0 200px;  /* fixed 200px, no grow/shrink */

  /* Override cross-axis alignment for one item */
  align-self: center;

  /* Change visual order (don't use for logical order) */
  order: 2;
}

/* Perfect horizontal + vertical centering */
.center {
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
}

/* Navigation bar — logo left, links right */
.navbar {
  display: flex;
  align-items: center;
  gap: 16px;
}
.navbar .spacer { flex: 1; }  /* pushes everything after it to the right */

/* Equal-width card row that wraps */
.cards {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
}
.card {
  flex: 1 1 280px;  /* grow/shrink but never narrower than 280px */
}
